// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(address baseToken, uint128 vBase, uint128 vNft) public {
        // Admissible domain: a real (non-zero) base token and sane virtual reserves
        vm.assume(baseToken != address(0));
        bound(uint256(vNft), 1, type(uint128).max);

        c.initialize(
            baseToken,
            address(this),
            vBase,
            vNft,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        // Rule: after initialize, c.baseToken() always equals the _baseToken argument.
        assertTrue(c.baseToken() == baseToken);
    }
}
